<h1>User detail</h1>
<section class="card grid two">
    <div><h2>Profile summary</h2><p><strong>Name:</strong> <?= e($profile['first_name'].' '.$profile['last_name']) ?></p><p><strong>Email:</strong> <?= e($profile['email']) ?></p><p><strong>Gender:</strong> <?= e($profile['gender']) ?></p><p><strong>Birthdate:</strong> <?= e($profile['birthdate']) ?></p></div>
    <div><h2>Onboarding</h2><p><span class="pill"><?= !empty($progress['is_complete']) ? 'Complete' : 'Incomplete' ?></span></p><p><strong>Completed steps:</strong> <?= (int)($progress['completed_steps'] ?? 0) ?></p><p><strong>Last updated:</strong> <?= e($progress['updated_at'] ?? 'Not started') ?></p></div>
</section>
<section class="card"><h2>Selected goals</h2><?php if (!$goals): ?><p>No goals selected.</p><?php endif; ?><div class="checks"><?php foreach ($goals as $goal): ?><span class="pill"><?= e($goal['title']) ?></span><?php endforeach; ?></div></section>
<section class="card"><h2>Dynamic answers</h2><?php foreach ($answers as $stepTitle => $groups): ?><section class="builder-section"><h3><?= e($stepTitle) ?></h3><?php foreach ($groups as $groupTitle => $rows): ?><h4><?= e($groupTitle) ?></h4><div class="table-wrap"><table><thead><tr><th>Question</th><th>Answer</th><th>Privacy</th><th>Matchable</th></tr></thead><tbody><?php foreach ($rows as $answer): $value = $answer['option_labels'] ?: ($answer['city_labels'] ?: ($answer['answer_text'] ?? $answer['answer_number'] ?? $answer['answer_date'] ?? ($answer['answer_boolean'] === null ? '' : ($answer['answer_boolean'] ? 'Yes' : 'No')))); ?><tr><td><?= e($answer['title']) ?></td><td><?= e((string)$value) ?></td><td><?= e($answer['privacy_level']) ?></td><td><?= $answer['is_matchable'] ? 'Yes' : 'No' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endforeach; ?></section><?php endforeach; ?></section>
